DO $patch$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.pipeline_transition(uuid,text,text,integer,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'uid IS NULL OR _side NOT IN','uid IS NULL OR _side IS NULL OR _side NOT IN'); definition:=replace(definition,'p.buyer_user_id<>uid','p.buyer_user_id IS DISTINCT FROM uid'); definition:=replace(definition,'(''ended'',''withdrawn'',''declined'')','(''ended'',''withdrawn'',''declined'',''revoked'')'); definition:=replace(definition,'p.loi_revision<>_version','_version IS NULL OR p.loi_revision IS DISTINCT FROM _version'); definition:=replace(definition,'amt<=0 OR amt>','amt<=0 OR amt<>trunc(amt) OR amt>'); definition:=replace(definition,'k NOT IN (''valuation'',''legal'')','k IS NULL OR k NOT IN (''valuation'',''legal'')'); definition:=replace(definition,'coalesce(_terms->>''supportName'',''Admin'')','''Admin'''); definition:=replace(definition,'IF w#>>ARRAY[''choices'',_side,''valuation'',''value'']', 'IF _terms->>''filePath'' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id=''pipeline-valuation'' AND o.name=_terms->>''filePath'' AND o.name ~ (''^pipeline-valuation/''||_id::text||''/''||_side||''/[0-9a-f-]{36}$'')) THEN RAISE EXCEPTION ''Invalid report attachment''; END IF; IF w#>>ARRAY[''choices'',_side,''valuation'',''value'']'); definition:=replace(definition,'''days'',days,''acceptedAt'',ts)', '''days'',days,''conditions'',CASE WHEN _action=''accept_revised'' THEN coalesce(p.loi_changes->>''conditions'',p.loi_conditions) ELSE p.loi_conditions END,''revision'',p.loi_revision+1,''acceptedAt'',ts)'); EXECUTE definition; END $patch$; COMMENT ON FUNCTION public.pipeline_transition(uuid,text,text,integer,jsonb) IS 'Authorised version-locked transitions with same-deal private valuation attachments; no browser storage policies on private pipeline-valuation bucket.';